  const ::flatbuffers::Vector<::flatbuffers::Offset<EVLEvent>> *EVENTS() const {
    return GetPointer<const ::flatbuffers::Vector<::flatbuffers::Offset<EVLEvent>> *>(VT_EVENTS);
  }
